/* ================================================================
   path-syllabus.js — the standard pre-internship / residency syllabus used
   to place every official past-exam question on the learning path.

   Each subject lists its exam chapters in curriculum order. A card is
   assigned to the chapter whose keywords match its stem/options best
   (see pathcurator.js → classifyCard). Keywords are regexes tested against
   the LOWER-CASED English + Persian text of the question.

   Sources consulted for the chapter lists: the Iranian Ministry of Health
   pre-internship (پیش‌کارورزی) and residency (دستیاری) exam blueprints, the
   reference books they cite (Harrison, Nelson, Williams, Schwartz, Robbins,
   Katzung, Smith Urology, Cummings ENT, Vaughan ophthalmology, Kaplan
   psychiatry, Fitzpatrick, Adams neurology, Park epidemiology) and the chapter
   structure of the shipped question booklets.
   ================================================================ */

const T = (slug, fa, en, kw) => ({ slug, fa, en, kw });

