function lit(list) {
  const out = [];
  for (const raw of list || []) {
    const k = String(raw).trim().toLowerCase();
    if (!k || KW_STOP.has(k)) continue;
    if (k.startsWith("\\b") || k.includes("(?")) { out.push(k); continue; }   // explicit regex fragment
    const esc = escapeRe(k);
    if (/^[a-z0-9]/.test(k) && /[a-z0-9]$/.test(k) && /^[a-z0-9 .\/&+\-:=;']*$/.test(k)) {
      out.push(`(?<![a-z0-9])${esc}(?![a-z0-9])`);                          // Latin token → word-bounded
    } else if ([...k.replace(/[\s\u200c]/g, "")].length <= 4) {
      out.push(`(?<![\u0600-\u06ff])${esc}(?![\u0600-\u06ff])`);          // short Persian stem → word-bounded
    } else out.push(esc);
  }
  return out;
}
function buildMerged(slug) {
  const base = SUBJECT_SYLLABUS[slug];
  if (!base) return null;
  const ex = {};
  for (const layer of [EXTRA_KW, EXTRA_KW2, EXTRA_KW3]) {
    for (const [k, v] of Object.entries(layer[slug] || {})) ex[k] = [...(ex[k] || []), ...v];
  }
  const neg = NEG_KW[slug] || {};
  let list = base.map((ch) => ({
    ...ch,
    kw: [...new Set([...(ch.kw || []), ...lit(ex[ch.slug])])],
    neg: lit(neg[ch.slug]),
  }));
  for (const extra of EXTRA_CHAPTERS[slug] || []) {
    if (list.some((c) => c.slug === extra.slug)) continue;
    const node = { slug: extra.slug, fa: extra.fa, en: extra.en, kw: lit(extra.kw), neg: lit(neg[extra.slug]) };
    if (extra.first) { list.unshift(node); continue; }
    const at = list.findIndex((c) => c.slug === extra.after);
    if (at >= 0) list.splice(at + 1, 0, node); else list.push(node);
  }
  return list;
}
export function syllabusFor(slug) {
  if (!mergedCache.has(slug)) mergedCache.set(slug, buildMerged(slug));
  return mergedCache.get(slug);
}
/* Subject → merged syllabus map (same shape as SUBJECT_SYLLABUS, used by analysis/tests). */
export function allSyllabi() {
  const out = {};
  for (const k of Object.keys(SUBJECT_SYLLABUS)) out[k] = syllabusFor(k);
  return out;
}
